forAll(genMethod, genPath, genToken, genPayload, func(method, path, token string, body []byte) bool {
    var captured *http.Request
    srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        captured = r
        w.WriteHeader(http.StatusOK)
        w.Write([]byte("{}"))
    }))
    defer srv.Close()
    c := newTestGitHubClient(Options{BaseURL: srv.URL, Token: token})
    _ = c.do(context.Background(), method, path, body, nil)
    ok := captured.Header.Get("Accept") == "application/vnd.github+json" &&
          captured.Header.Get("X-GitHub-Api-Version") == "2022-11-28" &&
          captured.Header.Get("User-Agent") != ""
    if token != "" {
        ok = ok && captured.Header.Get("Authorization") == "Bearer " + token
    } else {
        ok = ok && captured.Header.Get("Authorization") == ""
    }
    if len(body) > 0 {
        ok = ok && captured.Header.Get("Content-Type") == "application/json"
    }
    return ok
})

srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if strings.HasSuffix(r.URL.Path, "/comments") {
        if r.Header.Get("X-Fail-Comments") == "1" {
            w.WriteHeader(http.StatusInternalServerError)
            return
        }
        w.Write([]byte(`[{"body": "first comment", "user": {"login": "bob"}, "html_url": "https://cmt/1"}]`))
        return
    }
    w.Write([]byte(`{
        "number": 42,
        "title": "PR issue",
        "pull_request": {"url": "https://api.github.com/repos/o/r/pulls/42"}
    }`))
}))
defer srv.Close()
c := newTestGitHubClient(Options{BaseURL: srv.URL, Token: "tok"})
thread, err := c.ReadIssue(context.Background(), IssueRef{Repo: Repo{Owner: "o", Name: "r"}, Number: 42})
assert err == nil
assert thread.Issue.IsPR == true
assert len(thread.Comments) == 1
assert thread.Comments[0].Body == "first comment"

// Test partial comment failure resilience
cFail := newTestGitHubClient(Options{BaseURL: srv.URL, Token: "tok", HTTPClient: injectHeaderClient("X-Fail-Comments", "1")})
threadFail, errFail := cFail.ReadIssue(context.Background(), IssueRef{Repo: Repo{Owner: "o", Name: "r"}, Number: 42})
assert errFail == nil
assert threadFail.Issue.Number == 42
assert threadFail.CommentsErr != nil

srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if r.Method == "DELETE" {
        assert r.URL.Path == "/repos/o/r/issues/10/labels/special%20label"
        w.WriteHeader(http.StatusNotFound)
        return
    }
    if r.Method == "POST" {
        var body map[string]string
        json.NewDecoder(r.Body).Decode(&body)
        assert body["color"] == "ff0000" // leading # stripped
        w.WriteHeader(http.StatusUnprocessableEntity)
        w.Write([]byte(`{"message": "Validation Failed", "errors": [{"resource": "Label", "code": "already_exists", "field": "name"}]}`))
        return
    }
}))
defer srv.Close()
c := newTestGitHubClient(Options{BaseURL: srv.URL, Token: "tok"})
ref := IssueRef{Repo: Repo{Owner: "o", Name: "r"}, Number: 10}

errRem := c.RemoveLabel(context.Background(), ref, "special label")
assert errRem == nil

errCreate := c.CreateLabel(context.Background(), Repo{Owner: "o", Name: "r"}, Label{
    Name: "special label", Color: "#ff0000", Description: "desc",
})
assert errCreate == nil

srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if r.Method == "POST" {
        var body map[string]any
        json.NewDecoder(r.Body).Decode(&body)
        assert body["draft"] == true
        assert body["head"] == "feature"
        assert body["base"] == "main"
        w.WriteHeader(http.StatusCreated)
        w.Write([]byte(`{
            "number": 88, "title": "PR 88", "draft": true, "merged": false,
            "head": {"ref": "feature", "sha": "abc123"}, "base": {"ref": "main"}
        }`))
        return
    }
    w.Write([]byte(`{
        "number": 88, "title": "PR 88", "draft": true, "merged": false,
        "head": {"ref": "feature", "sha": "abc123"}, "base": {"ref": "main"}
    }`))
}))
defer srv.Close()
c := newTestGitHubClient(Options{BaseURL: srv.URL, Token: "tok"})
pr, err := c.CreatePullRequest(context.Background(), Repo{Owner: "o", Name: "r"}, CreatePullRequestRequest{
    Title: "PR 88", Head: "feature", Base: "main", Draft: true,
})
assert err == nil
assert pr.Number == 88
assert pr.Draft == true
assert pr.Merged == false

readPR, errRead := c.ReadPullRequest(context.Background(), IssueRef{Repo: Repo{Owner: "o", Name: "r"}, Number: 88})
assert errRead == nil
assert readPR.HeadBranch == "feature"
assert readPR.HeadSHA == "abc123"
assert readPR.BaseBranch == "main"

srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if strings.HasSuffix(r.URL.Path, "/files") {
        w.Write([]byte(`[
            {"filename": "a.go", "status": "added", "additions": 10, "deletions": 0},
            {"filename": "b.go", "status": "modified", "additions": 2, "deletions": 1},
            {"filename": "c.go", "status": "removed", "additions": 0, "deletions": 5}
        ]`))
        return
    }
    if r.Method == "PATCH" {
        var body map[string]any
        json.NewDecoder(r.Body).Decode(&body)
        assert body["state"] == "closed"
        w.Write([]byte(`{"state": "closed"}`))
        return
    }
    // GET /pulls/5
    w.Write([]byte(`{"number": 5, "state": "closed", "merged": true, "head": {"sha": "sha1"}}`))
}))
defer srv.Close()
c := newTestGitHubClient(Options{BaseURL: srv.URL, Token: "tok"})
ref := IssueRef{Repo: Repo{Owner: "o", Name: "r"}, Number: 5}

files, errFiles := c.ReadChangedFiles(context.Background(), ref)
assert errFiles == nil
assert len(files) == 3
assert files[2].Status == "deleted" // mapped from removed to deleted

st, errSt := c.GetPRState(context.Background(), ref)
assert errSt == nil
assert st.State == "merged" // merged=true overrides closed
assert st.Merged == true

errClose := c.ClosePullRequest(context.Background(), ref)
assert errClose == nil

var mergeMethodSent string
var returnConflict bool
srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if r.Method == "GET" && r.URL.Path == "/repos/o/r" {
        // repo settings: merge commit disabled, squash enabled
        w.Write([]byte(`{"allow_merge_commit": false, "allow_squash_merge": true, "allow_rebase_merge": true}`))
        return
    }
    if r.Method == "PUT" && strings.HasSuffix(r.URL.Path, "/merge") {
        if returnConflict {
            w.WriteHeader(http.StatusMethodNotAllowed) // 405
            w.Write([]byte(`{"message": "Pull Request is not mergeable"}`))
            return
        }
        var body map[string]any
        json.NewDecoder(r.Body).Decode(&body)
        mergeMethodSent = body["merge_method"].(string)
        w.WriteHeader(http.StatusOK)
        w.Write([]byte(`{"merged": true, "sha": "merged_sha_99", "message": "Pull Request successfully merged"}`))
        return
    }
}))
defer srv.Close()
c := newTestGitHubClient(Options{BaseURL: srv.URL, Token: "tok"})
ref := IssueRef{Repo: Repo{Owner: "o", Name: "r"}, Number: 10}

// Explicit squash
res, err := c.MergePullRequest(context.Background(), ref, MergeOptions{Method: MergeMethodSquash})
assert err == nil
assert res.Merged == true
assert mergeMethodSent == "squash"

// Default method: queries repo, selects squash since merge_commit is false
resDef, errDef := c.MergePullRequest(context.Background(), ref, MergeOptions{Method: MergeMethodDefault})
assert errDef == nil
assert resDef.Merged == true
assert mergeMethodSent == "squash"

// Conflict on 405/409
returnConflict = true
_, errConflict := c.MergePullRequest(context.Background(), ref, MergeOptions{})
assert issuex.IsConflict(errConflict) == true

srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    w.WriteHeader(http.StatusOK)
    // Stream 9 MB of data
    chunk := make([]byte, 1024*1024)
    for i := 0; i < 9; i++ {
        w.Write(chunk)
    }
}))
defer srv.Close()
c := newTestGitHubClient(Options{BaseURL: srv.URL, Token: "tok"})
var buf bytes.Buffer
err := c.do(context.Background(), "GET", "/test", nil, &buf)
// Body reading is truncated at 8,388,608 bytes via io.LimitReader
assert buf.Len() <= 8*1024*1024

forAll(genErrorMessage, genFieldErrors, func(msg string, fieldErrs []fieldError) bool {
    payload, _ := json.Marshal(map[string]any{
        "message": msg,
        "errors": fieldErrs,
    })
    httpErr := parseGitHubError(http.StatusUnprocessableEntity, "POST", "/repos/o/r/labels", payload)
    expectedPrefix := msg
    if !strings.Contains(httpErr.Error(), expectedPrefix) {
        return false
    }
    for _, fe := range fieldErrs {
        if !strings.Contains(httpErr.Error(), fe.Field) || !strings.Contains(httpErr.Error(), fe.Code) {
            return false
        }
    }
    return true
})

